        if await main.count() == 0:
            return []

        articles = main.get_by_role("article")
        cnt = await articles.count()
        results = []
        for i in range(cnt):
            article = articles.nth(i)

            # Prefer heading -> link pattern
            title_text = None
            href = None
            try:
                heading = article.get_by_role("heading")
                if await heading.count() > 0:
                    head = heading.first
                    link_in_heading = head.get_by_role("link")
                    if await link_in_heading.count() > 0:
                        link = link_in_heading.first
                        try:
                            title_text = (await link.inner_text()).strip()
                        except Exception:
                            title_text = ""
                        try:
                            href = await link.get_attribute("href")
                        except Exception:
                            href = None
                # Fallback: first link inside the article
                if not title_text:
                    links = article.get_by_role("link")
                    if await links.count() > 0:
                        link = links.first
                        try:
                            title_text = (await link.inner_text()).strip()
                        except Exception:
                            title_text = ""
                        try:
                            href = await link.get_attribute("href")
                        except Exception:
                            href = None
            except Exception:
                # If any DOM read fails for this article, skip gracefully
                continue

            if title_text:
                # Compare case-insensitively for exact match or substring
                if title_text.strip().lower() == keyword.strip().lower() or keyword.strip().lower() in title_text.strip().lower():
                    results.append({"title": title_text, "url": href})
                    # We can stop after finding the matching article
                    break

        # Print the raw results and return them
        print(results)
        return results

    except Exception:
        return []
